# ---------------------------------------------------------------- ортақ шағын тіл: лексер
LEX = ("import re\n\n"
       "TOKENS = [\n"
       "    ('NUM',  r'\\d+'),\n"
       "    ('ID',   r'[A-Za-z_]\\w*'),\n"
       "    ('OP',   r'==|<=|>=|[-+*/()<>=^]'),\n"
       "    ('SKIP', r'\\s+'),\n"
       "]\n"
       "MASTER = re.compile('|'.join(f'(?P<{n}>{p})' for n, p in TOKENS))\n\n"
       "def lex(src):\n"
       "    out, i = [], 0\n"
       "    while i < len(src):\n"
       "        m = MASTER.match(src, i)\n"
       "        if not m:\n"
       "            raise SyntaxError(f'{i}-орында белгісіз таңба {src[i]!r}')\n"
       "        if m.lastgroup != 'SKIP':\n"
       "            out.append((m.lastgroup, m.group()))\n"
       "        i = m.end()\n"
       "    return out\n")

# ---------------------------------------------------------------- 1-сабақ
PIPE = (LEX + "\n"
        "def parse(tokens):\n"
        "    \"\"\"өрнек: сан (+|-) сан ... -> ағаш (сол жақтан топтасады)\"\"\"\n"
        "    pos = 0\n"
        "    def num():\n"
        "        nonlocal pos\n"
        "        kind, text = tokens[pos]; pos += 1\n"
        "        return ('num', int(text))\n"
        "    tree = num()\n"
        "    while pos < len(tokens):\n"
        "        op = tokens[pos][1]; pos += 1\n"
        "        tree = (op, tree, num())\n"
        "    return tree\n\n"
        "def evaluate(t):                      # интерпретатор\n"
        "    if t[0] == 'num':\n"
        "        return t[1]\n"
        "    a, b = evaluate(t[1]), evaluate(t[2])\n"
        "    return a + b if t[0] == '+' else a - b\n\n"
        "def compile_(t):                      # компилятор: ағаш -> стек машинасының командалары\n"
        "    if t[0] == 'num':\n"
        "        return [('PUSH', t[1])]\n"
        "    return compile_(t[1]) + compile_(t[2]) + [('ADD',) if t[0] == '+' else ('SUB',)]\n\n"
        "def run(code):\n"
        "    st = []\n"
        "    for ins in code:\n"
        "        if ins[0] == 'PUSH':\n"
        "            st.append(ins[1])\n"
        "        else:\n"
        "            b, a = st.pop(), st.pop()\n"
        "            st.append(a + b if ins[0] == 'ADD' else a - b)\n"
        "    return st.pop()\n\n"
        "src = '10 - 3 + 7 - 2'\n"
        "toks = lex(src)\n"
        "tree = parse(toks)\n"
        "code = compile_(tree)\n"
        "print('токендер:', toks)\n"
        "print('ағаш:', tree)\n"
        "print('код:', code)\n"
        "print('интерпретатор:', evaluate(tree), ' компилятор + VM:', run(code))")

