# ---------------------------------------------------------------- 4-сабақ
RD = (LEX + "\n"
      "class Parser:\n"
      "    \"\"\"expr   -> term (('+'|'-') term)*\n"
      "       term   -> factor (('*'|'/') factor)*\n"
      "       factor -> NUM | ID | '(' expr ')' | '-' factor\"\"\"\n"
      "    def __init__(self, tokens):\n"
      "        self.t, self.i = tokens, 0\n"
      "    def peek(self):\n"
      "        return self.t[self.i][1] if self.i < len(self.t) else None\n"
      "    def eat(self, text=None):\n"
      "        if self.i >= len(self.t) or (text and self.t[self.i][1] != text):\n"
      "            raise SyntaxError(f'{self.i}-токенде {text!r} күтілді, келгені {self.peek()!r}')\n"
      "        self.i += 1\n"
      "        return self.t[self.i - 1]\n"
      "    def expr(self):\n"
      "        node = self.term()\n"
      "        while self.peek() in ('+', '-'):\n"
      "            op = self.eat()[1]\n"
      "            node = (op, node, self.term())\n"
      "        return node\n"
      "    def term(self):\n"
      "        node = self.factor()\n"
      "        while self.peek() in ('*', '/'):\n"
      "            op = self.eat()[1]\n"
      "            node = (op, node, self.factor())\n"
      "        return node\n"
      "    def factor(self):\n"
      "        if self.peek() == '(':\n"
      "            self.eat('(')\n"
      "            node = self.expr()\n"
      "            self.eat(')')\n"
      "            return node\n"
      "        if self.peek() == '-':\n"
      "            self.eat('-')\n"
      "            return ('neg', self.factor())\n"
      "        kind, text = self.eat()\n"
      "        return ('num', int(text)) if kind == 'NUM' else ('var', text)\n\n"
      "def parse(src):\n"
      "    p = Parser(lex(src))\n"
      "    tree = p.expr()\n"
      "    if p.peek() is not None:\n"
      "        raise SyntaxError(f'артық токен: {p.peek()!r}')\n"
      "    return tree\n")

RD_DEMO = (RD + "\n"
           "for src in ['8 - 4 - 2', '2 + 3 * 4', '(2 + 3) * -4', '2 * (3 + ', '1 2']:\n"
           "    try:\n"
           "        print(f'{src!r:15} ->', parse(src))\n"
           "    except SyntaxError as e:\n"
           "        print(f'{src!r:15} -> ҚАТЕ: {e}')")

