PRATT = (LEX + "\n"
         "# байланыс күші: (сол жақ күш, оң жақ күш). Сол топтасу: оң = сол + 1; оң топтасу: оң = сол.\n"
         "BP = {'+': (10, 11), '-': (10, 11), '*': (20, 21), '/': (20, 21), '^': (31, 30), '==': (5, 6), '<': (5, 6)}\n\n"
         "def parse(src):\n"
         "    toks = [t for _, t in lex(src)]\n"
         "    pos = 0\n"
         "    def expr(min_bp):\n"
         "        nonlocal pos\n"
         "        t = toks[pos]; pos += 1\n"
         "        if t == '(':\n"
         "            left = expr(0); pos += 1          # ')'\n"
         "        elif t == '-':\n"
         "            left = ('neg', expr(25))          # унарлы минус: * пен ^ арасында\n"
         "        else:\n"
         "            left = int(t) if t.isdigit() else t\n"
         "        while pos < len(toks) and toks[pos] in BP:\n"
         "            op = toks[pos]\n"
         "            lbp, rbp = BP[op]\n"
         "            if lbp < min_bp:\n"
         "                break\n"
         "            pos += 1\n"
         "            left = (op, left, expr(rbp))\n"
         "        return left\n"
         "    return expr(0)\n\n"
         "for src in ['2 ^ 3 ^ 2', '8 - 4 - 2', '1 + 2 * 3 == 7', '-2 ^ 2', '(1 + 2) * 3']:\n"
         "    print(f'{src:16} -> {parse(src)}')")

